<?php
namespace App\Http\Controllers;
use App\Models\Supplier;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class SupplierController extends Controller { private function manager(Request $request):void{abort_unless($request->user()?->isManager(),403);} public function index(Request $request){$suppliers=Supplier::query()->when($request->q,fn($q,$term)=>$q->where(fn($x)=>$x->where('name','like','%'.$term.'%')->orWhere('contact_person','like','%'.$term.'%')->orWhere('phone','like','%'.$term.'%')))->orderBy('name')->paginate(12)->withQueryString();return view('suppliers.index',compact('suppliers'));} public function create(Request $request){$this->manager($request);return view('suppliers.form',['supplier'=>new Supplier]);} public function store(Request $request){$this->manager($request);Supplier::create($this->validated($request));return redirect()->route('suppliers.index')->with('success','Supplier added successfully.');} public function edit(Request $request,Supplier $supplier){$this->manager($request);return view('suppliers.form',compact('supplier'));} public function update(Request $request,Supplier $supplier){$this->manager($request);$supplier->update($this->validated($request,$supplier));return redirect()->route('suppliers.index')->with('success','Supplier updated successfully.');} public function destroy(Request $request,Supplier $supplier){$this->manager($request);$supplier->delete();return back()->with('success','Supplier archived.');} private function validated(Request $request,?Supplier $supplier=null):array{return $request->validate(['name'=>['required','string','max:150'],'contact_person'=>['nullable','string','max:150'],'email'=>['nullable','email','max:190'],'phone'=>['nullable','string','max:50'],'address'=>['nullable','string','max:1000'],'tax_number'=>['nullable','string','max:80',Rule::unique('suppliers','tax_number')->ignore($supplier?->id)],'status'=>['required',Rule::in(['active','inactive'])],'notes'=>['nullable','string','max:2000']]);}}
